# Initially generated by GitHub Copilot.
"""Composite the five Psalm-5v9 source screenshots into a single slide.

Layout (on a teal gradient background, 2560×1440):
  Row 1: AHT     (full width)
  Row 2: MwD     (full width)
  Row 3: Sefaria (full width)
  Row 4: WS1 and WS2 side by side
"""

import pathlib

from PIL import Image

from slide_generator import slide_render

_IMG_SRC = pathlib.Path("misc/mam-is-a-dataset/img-sources")

_PADDING = 60  # px left/right and top/bottom
_GAP = 30  # px between rows and between the two WS images

_SOURCES = {
    "aht": _IMG_SRC / "Psalm 5v9 AHT.png",
    "mwd": _IMG_SRC / "Psalm 5v9 MwD.png",
    "sefaria": _IMG_SRC / "Psalm 5v9 Sefaria.png",
    "ws1": _IMG_SRC / "Psalm 5v9 WS1.png",
    "ws2": _IMG_SRC / "Psalm 5v9 WS2.png",
}


def _fit(img: Image.Image, max_w: int, max_h: int) -> Image.Image:
    """Return a copy of *img* scaled to fit within (max_w, max_h), preserving aspect ratio."""
    scale = min(max_w / img.width, max_h / img.height)
    new_w = max(1, round(img.width * scale))
    new_h = max(1, round(img.height * scale))
    return img.resize((new_w, new_h), Image.LANCZOS)


def _paste_centered_in_row(
    canvas: Image.Image, img: Image.Image, row_y: int, row_h: int
) -> None:
    """Paste *img* horizontally centered in a row region."""
    x = (slide_render.W - img.width) // 2
    y = row_y + (row_h - img.height) // 2
    canvas.paste(img, (x, y))


def render_psalm_5v9_sources(images_dir: pathlib.Path) -> None:
    """Render slide-psalm-5v9-sources.png into *images_dir*."""
    W, H = slide_render.W, slide_render.H

    # Usable area
    usable_w = W - 2 * _PADDING
    # 4 rows with 3 inter-row gaps
    usable_h = H - 2 * _PADDING - 3 * _GAP
    row_h = usable_h // 4

    # WS pair: each panel is half the usable width minus half the gap
    ws_panel_w = (usable_w - _GAP) // 2

    canvas = slide_render.make_gradient(
        top_rgb=(13, 94, 87),
        bot_rgb=(8, 61, 56),
    )

    row_tops = [_PADDING + i * (row_h + _GAP) for i in range(4)]

    # Rows 0-2: single full-width images
    for key, row_y in zip(("aht", "mwd", "sefaria"), row_tops[:3]):
        src = Image.open(_SOURCES[key]).convert("RGB")
        fitted = _fit(src, usable_w, row_h)
        _paste_centered_in_row(canvas, fitted, row_y, row_h)

    # Row 3: WS1 left, WS2 right
    ws_row_y = row_tops[3]
    for key, panel_left in (("ws1", _PADDING), ("ws2", _PADDING + ws_panel_w + _GAP)):
        src = Image.open(_SOURCES[key]).convert("RGB")
        fitted = _fit(src, ws_panel_w, row_h)
        x = panel_left + (ws_panel_w - fitted.width) // 2
        y = ws_row_y + (row_h - fitted.height) // 2
        canvas.paste(fitted, (x, y))

    dest = images_dir / "slide-psalm-5v9-sources.png"
    dest.parent.mkdir(parents=True, exist_ok=True)
    canvas.save(dest)
    slide_render.write_provenance(dest, "mam-is-a-dataset", "psalm-5v9-sources")
    print(f"Saved {dest} {canvas.size}")
